import { chromium } from "playwright";
const b = await chromium.launch(); const p = await b.newPage({viewport:{width:1586,height:992}});
await p.goto("http://localhost:3200/document",{waitUntil:"networkidle"});
const r = await p.evaluate(()=>{const out=[];document.querySelectorAll('*').forEach(e=>{const s=getComputedStyle(e);if(/(auto|scroll)/.test(s.overflowY)&&e.scrollHeight>e.clientHeight+2){const r=e.getBoundingClientRect();out.push([e.tagName,e.className.slice(0,60),Math.round(r.x),Math.round(r.y),Math.round(r.width),Math.round(r.height),e.scrollHeight,e.clientHeight])}});return {out,docH:document.documentElement.scrollHeight,docW:document.documentElement.scrollWidth}});
console.log(JSON.stringify(r,null,1));
await b.close();
EOF
